#define CROW_HIP_ROLL_LIBRARY
#include "../crow-v15-hip-roll-strong-drive-prototype-20261111/probe.cpp"
#include <iomanip>
int main(){try{auto robot=hipRollModel();const auto& m=robot.mechanics;std::cout<<std::setprecision(17);int lane,step;while(std::cin>>lane>>step){std::vector<double> q(m.defaultQ.size()),v(m.defaultV.size());for(double& x:q)need(bool(std::cin>>x),"missing q");for(double& x:v)need(bool(std::cin>>x),"missing v");std::vector<ArticulatedBodyKinematics> k(m.bodies.size());auto s=computeArticulatedBodyKinematics(m,0,q,v,k);need(s.succeeded(),"kinematics");double mass=0,p[3]={},vel[3]={};for(unsigned i=0;i<m.bodyNames.size();++i){double w=m.bodies[i].massAndInverseMass.x;mass+=w;for(int j=0;j<3;++j){p[j]+=w*k[i].centerOfMassPosition[j];vel[j]+=w*k[i].linearVelocity[j];}}std::cout<<lane<<" "<<step<<" "<<mass;for(double x:p)std::cout<<" "<<x/mass;for(double x:vel)std::cout<<" "<<x/mass;std::cout<<"\n";}}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
